			value = 1
			if = {
				limit = {
					scope:target_country = {
						is_subject_of = root
						is_diplomatic_play_enemy_of = root
						scope:diplomatic_play ?= {
							initiator_is = scope:target_country
						}
					}
				}
				multiply = define:NDiplomacy|WAR_GOAL_INFAMY_REBELLING_SUBJECT_MULT
			}
		}
		multiply = { desc = state_aor1776_imperial_conquest_infamy_mult value = 1 add = scope:target_state.modifier:state_aor1776_imperial_conquest_infamy_mult }
	}

	on_enforced = {
